// 왼쪽 그리드뷰에서 오른쪽 그리드뷰로 drag&drop 할 시 
 scwin.dragStart = function (info) {
    var parentRowIndex = info.parentRowIndex;
    var parentRowData = info.parentRowData;
    var beforeRemoveRowIndex = info.beforeRemoveRowIndex;
    var beforeRemoveData = info.beforeRemoveData;
    // dragStart 함수안에서 쓸 인자가 필요하시면 해당 인자를 사용하시면 됩니다.
    //alert("dragStart 함수 호출");
    console.log("dragStart 함수 호출")        
    return true; // true인 경우에만 drilldown dragDrop을 실행한다. -> dragEnd 함수로 인자를 넘긴다

}

scwin.dragEnd = function (toIndex, rowXml, info) {
    //첫번째 인자값으로는 toIndex가 주어지는데 drilldown을 사용하였기 때문에, 
    // targetIndex의 realRowIndex를 계산한 값이라고 보면 된다.

    //dragStart함수의 info 인자를 새롭게 선언. 필요한 인자를 사용하시면 됩니다.
    var removedData = info.removedData;
    var removedRowIndex = info.removedRowIndex; // dragStart한 row 위치
    var fromRowIndex = info.fromRowIndex;
    var toRowIndex = info.toRowIndex;
    var rowJSON = info.rowJSON; // 데이터 값
    console.log(info)
    //alert("dragEnd 함수 호출");
    console.log("dragEnd 함수 호출")    
    dataList1.removeRow(fromRowIndex);
    dataList2.insertJSON(toIndex, rowJSON);
    //dataList2.setRowJSON(toIndex, rowJSON);

}

 // 오른쪽 그리드뷰에서 왼쪽 그리드뷰로 drag&drop 할 시 
scwin.dragStart2 = function (info) {
    var parentRowIndex2 = info.parentRowIndex;
    var parentRowData2 = info.parentRowData;
    var beforeRemoveRowIndex2 = info.beforeRemoveRowIndex;
    var beforeRemoveData2 = info.beforeRemoveData;
    // dragStart2 함수안에서 쓸 인자가 필요하시면 해당 인자를 사용하시면 됩니다.
    //alert("dragStart2 함수 호출");
    console.log("dragStart2 함수 호출")
    return true; // true인 경우에만 drilldown dragDrop을 실행한다. -> dragEnd 함수로 인자를 넘긴다

}

scwin.dragEnd2 = function (toIndex, rowXml, info) {
    //첫번째 인자값으로는 toIndex가 주어지는데 drilldown을 사용하였기 때문에, 
    // targetIndex의 realRowIndex를 계산한 값이라고 보면 된다.

    //dragStart함수의 info 인자를 새롭게 선언. 필요한 인자를 사용하시면 됩니다.
    var removedData = info.removedData;
    var removedRowIndex = info.removedRowIndex; // dragStart한 row 위치
    var fromRowIndex = info.fromRowIndex;
    var toRowIndex = info.toRowIndex;
    var rowJSON = info.rowJSON; // 데이터 값
    //alert("dragEnd2 함수 호출");
    console.log("dragEnd2 함수 호출")
    dataList2.removeRow(removedRowIndex);
    dataList1.setRowJSON(toIndex, rowJSON);

} 


	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#gridView1_cell_0_1', 'drag-n-drop', {
			dx: 300,
			dy: 0
		});
	}
	scwin.checkFirstColumnValues = function() {	
		var tbody = WebSquare.wUnit.getDomById("gridView2_body_tbody");
		var rows = Array.from(tbody.getElementsByTagName("tr"));
		var firstColumnValues = [];
		let reVal = false;
		rows.forEach( (row, index) => {
			if(index < 3){
				var secondCell = row.getElementsByTagName("td")[1];
				if (secondCell) {
					firstColumnValues.push(secondCell.innerText.trim()); 
				}
			}
		});

		var expectedValues = ["원", "투", "쓰리"];
		var isMatch = JSON.stringify(firstColumnValues) === JSON.stringify(expectedValues);

		if (isMatch) {
			console.log("첫 번째 컬럼의 값이 올바릅니다.");
			reVal = true;
		} else {
			console.log("첫 번째 컬럼의 값이 일치하지 않습니다.");
		}
		return reVal;
	}	

	scwin.checkVal = function() {
		return scwin.checkFirstColumnValues();
	}	
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "300");		

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
